CREATE TABLE seed_source_registry(seed_id VARCHAR PRIMARY KEY,source_id VARCHAR NOT NULL REFERENCES evidence_sources(source_id),requested_doi VARCHAR NOT NULL,requested_pmid VARCHAR,purpose VARCHAR NOT NULL);
CREATE TABLE metadata_candidates(candidate_id VARCHAR PRIMARY KEY,seed_id VARCHAR NOT NULL,source_id VARCHAR NOT NULL REFERENCES evidence_sources(source_id),provider VARCHAR NOT NULL,doi VARCHAR,pmid VARCHAR,pmcid VARCHAR,title VARCHAR,publication_year INTEGER,response_hash VARCHAR NOT NULL,retrieval_event_id VARCHAR NOT NULL REFERENCES source_retrieval_events(retrieval_id),record_json JSON NOT NULL,record_hash VARCHAR NOT NULL);
CREATE TABLE metadata_comparisons(comparison_id VARCHAR PRIMARY KEY,seed_id VARCHAR NOT NULL,source_id VARCHAR NOT NULL,provider_a VARCHAR NOT NULL,provider_b VARCHAR NOT NULL,field_name VARCHAR NOT NULL,classification VARCHAR NOT NULL,record_json JSON NOT NULL,record_hash VARCHAR NOT NULL);
CREATE TABLE bibliographic_audits(seed_id VARCHAR PRIMARY KEY,source_id VARCHAR NOT NULL REFERENCES evidence_sources(source_id),status VARCHAR NOT NULL,verified_doi VARCHAR,verified_pmid VARCHAR,doi_pmid_link_verified BOOLEAN NOT NULL,relevance_status VARCHAR NOT NULL,open_access BOOLEAN,manual_review_required BOOLEAN NOT NULL,record_json JSON NOT NULL,record_hash VARCHAR NOT NULL);
CREATE INDEX metadata_candidate_source_idx ON metadata_candidates(seed_id,provider);
CREATE INDEX metadata_comparison_source_idx ON metadata_comparisons(seed_id,classification);
